-- V20: 算法题库（500题）
-- 简单 150 / 中等 250 / 困难 100
-- 覆盖 24 个分类：数组、链表、树、图、动态规划、贪心、回溯、双指针、哈希表、栈、队列、堆、二分查找、滑动窗口、拓扑排序、并查集、Trie、位运算、数学、字符串、排序、递归、分治、二叉搜索树

CREATE TABLE IF NOT EXISTS algorithm_questions (
    id              BIGINT NOT NULL,
    title           VARCHAR(200) NOT NULL,
    difficulty      VARCHAR(10) NOT NULL,  -- 简单/中等/困难
    category        VARCHAR(40) NOT NULL,
    acceptance      VARCHAR(10),
    description     TEXT NOT NULL,
    sort_order      INTEGER NOT NULL DEFAULT 0,
    status          VARCHAR(10) NOT NULL DEFAULT 'ACTIVE',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_algo_difficulty ON algorithm_questions(difficulty);
CREATE INDEX IF NOT EXISTS idx_algo_category ON algorithm_questions(category);
CREATE INDEX IF NOT EXISTS idx_algo_sort ON algorithm_questions(sort_order);

